import {CHICKEN} from './chicken-config.js';
/** @param {import('./engine.js').State} state */
export function advanceChickenMission(state){const c=state.chicken;if(!c?.visited||!c.coop)return;const done=[true,c.stats.feedActions>0,c.stats.waterActions>0,c.stats.cleaned>0,c.stats.laid>0,c.stats.collected>0,c.stats.sold>0,c.coop.level>=1];while(c.mission.step<8&&done[c.mission.step])c.mission.step++;}
/** Shared ledger, independent namespace, exactly-once chapter award. @param {import('./engine.js').State} state @param {import('./engine.js').DomainEvent[]} events @param {import('./chicken-runtime.js').Transaction} transact @param {number} commandId */
export function awardChickenRewards(state,events,transact,commandId){const c=state.chicken;if(!c?.visited)return;const rewards=[{id:'chicken.chapter1',ready:c.mission.step>=7,amount:CHICKEN.chapterReward},{id:'chicken.healthy',ready:c.stats.healthyDays>=3,amount:CHICKEN.healthyReward},{id:'chicken.bigger',ready:!!c.coop&&c.coop.level>=1&&c.hens.length>=3,amount:CHICKEN.biggerReward}];for(const reward of rewards)if(reward.ready&&!c.grants.includes(reward.id)){c.grants.push(reward.id);transact(state,'mission_reward',reward.amount,commandId+':'+reward.id);events.push({type:'missionReward',amount:reward.amount});}}
/** One active objective shared by panel and guide. @param {import('./engine.js').State} state */
export function chickenObjective(state){const c=state.chicken,step=c?.mission.step||0;if(c&&step===8){if(!c.grants.includes('chicken.healthy'))return {step,title:'healthyHens',detail:'healthyHensTip',target:'[data-choose-chicken=coop]',progress:Math.min(3,c.stats.healthyDays)+'/3'};if(!c.grants.includes('chicken.bigger'))return {step,title:'biggerCoop',detail:'biggerCoopTip',target:'#market-open',progress:Math.min(3,c.hens.length)+'/3'};if(!c.grants.includes('chicken.order.first'))return {step,title:'eggOrderTitle',detail:'eggOrderDescription',target:'#market-open',progress:Math.min(CHICKEN.orderCount,c.inventory.reduce((n,l)=>n+l.quantity,0))+'/'+CHICKEN.orderCount};}return {step,title:'chickenMission'+step,detail:'chickenDetail'+step,target:['#area-chicken','[data-choose-chicken=feeder]','[data-choose-chicken=drinker]','[data-choose-chicken=clean]','#next-day','[data-choose-chicken=nest]','#market-open','#market-open',''][step],progress:''};}
